insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52770', 'Spaghetti bolognaise', 'https://www.themealdb.com/images/media/meals/sutysw1468247559.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52770', 'Recette adaptée de TheMealDB', 40, 4, '["Faire revenir les oignons émincés dans l''huile à feu assez vif pendant 3 à 4 minutes.","Ajouter l''ail et la viande hachée et laisser dorer.","Ajouter les champignons et l''origan, cuire encore 2 minutes.","Verser les tomates, le bouillon, le concentré de tomate et la sauce Worcestershire, saler et poivrer. Porter à ébullition puis laisser mijoter 30 minutes à couvert, en remuant de temps en temps.","Pendant ce temps, cuire les spaghetti dans de l''eau bouillante salée selon le temps indiqué sur le paquet, puis les égoutter.","Mélanger les spaghetti à la sauce et servir dans des assiettes chaudes, avec du parmesan."]'::jsonb, '["2 oignons","1 cuillère à soupe d''huile d''olive","1 gousse d''ail","500 g de bœuf haché maigre","90 g de champignons","1 cuillère à café d''origan séché","1 boîte de 400 g de tomates concassées","300 ml de bouillon de bœuf chaud","1 cuillère à soupe de concentré de tomate","1 cuillère à soupe de sauce Worcestershire","350 g de spaghetti","parmesan râpé"]'::jsonb, 'Italian', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52844', 'Lasagnes à la bolognaise', 'https://www.themealdb.com/images/media/meals/wtsvxx1511296896.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52844', 'Recette adaptée de TheMealDB', 90, 6, '["Chauffer l''huile dans une grande casserole, y faire dorer le lard coupé en petits morceaux.","Ajouter l''oignon, le céleri et la carotte et cuire 5 minutes à feu moyen. Ajouter l''ail une minute, puis la viande hachée, que l''on fait brunir 6 minutes en l''émiettant.","Incorporer le concentré de tomate, puis les tomates concassées et le miel. Saler, poivrer et laisser mijoter 20 minutes.","Préchauffer le four à 200 °C. Dans un grand plat, alterner une couche de sauce et une couche de feuilles de lasagne, sur 3 étages, en terminant par des feuilles.","Détendre la crème fraîche avec 2 cuillères à soupe d''eau, la verser sur le dessus, ajouter la mozzarella et le parmesan.","Cuire 25 à 30 minutes jusqu''à ce que le dessus soit doré. Servir avec du basilic."]'::jsonb, '["1 cuillère à soupe d''huile d''olive","2 tranches de lard","1 oignon finement haché","1 branche de céleri","1 carotte","2 gousses d''ail hachées","500 g de bœuf haché","1 cuillère à soupe de concentré de tomate","800 g de tomates concassées","1 cuillère à soupe de miel","500 g de feuilles de lasagne","400 ml de crème fraîche","125 g de mozzarella","50 g de parmesan","quelques feuilles de basilic"]'::jsonb, 'Italian', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52982', 'Spaghetti à la carbonara', 'https://www.themealdb.com/images/media/meals/llcbn01574260722.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52982', 'Recette adaptée de TheMealDB', 30, 4, '["Porter à ébullition une grande casserole d''eau salée.","Battre les jaunes d''œufs avec le fromage râpé et beaucoup de poivre.","Cuire les spaghetti 10 minutes, jusqu''à ce qu''ils soient al dente.","Pendant ce temps, faire dorer les lardons avec l''ail écrasé et un peu de beurre pendant 5 minutes, puis retirer l''ail.","Égoutter les pâtes en gardant un peu d''eau de cuisson, les ajouter aux lardons dans la poêle, hors du feu.","Verser le mélange œufs-fromage, mélanger vite en ajoutant un peu d''eau de cuisson pour obtenir une sauce crémeuse. Servir tout de suite."]'::jsonb, '["320 g de spaghetti","6 jaunes d''œufs","sel","150 g de lardons ou de pancetta","50 g de pecorino râpé","poivre noir du moulin","1 gousse d''ail","un peu de beurre"]'::jsonb, 'Italian', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52771', 'Penne all''arrabbiata', 'https://www.themealdb.com/images/media/meals/ustsqw1468250014.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52771', 'Recette adaptée de TheMealDB', 25, 4, '["Cuire les penne dans de l''eau bouillante salée, environ 9 minutes.","Dans une grande poêle, chauffer l''huile puis faire revenir l''ail 1 à 2 minutes.","Ajouter les tomates, le piment, les herbes italiennes, du sel et du poivre. Cuire 5 minutes à gros bouillons.","Hors du feu, ajouter le basilic ciselé.","Égoutter les pâtes, les mélanger à la sauce et servir avec des copeaux de parmesan."]'::jsonb, '["450 g de penne","4 cuillères à soupe d''huile d''olive","3 gousses d''ail","1 boîte de tomates concassées","1/2 cuillère à café de piment en flocons","1/2 cuillère à café d''herbes italiennes","6 feuilles de basilic","parmesan"]'::jsonb, 'Italian', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52796', 'Poulet Alfredo aux légumes et pâtes papillon', 'https://www.themealdb.com/images/media/meals/syqypv1486981727.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52796', 'Recette adaptée de TheMealDB', 50, 5, '["Faire cuire les blancs de poulet salés et poivrés 5 à 7 minutes de chaque côté dans du beurre et de l''huile, puis les réserver.","Cuire les pâtes dans l''eau bouillante salée, en gardant un peu d''eau de cuisson avant d''égoutter.","Dans la même poêle, faire revenir les légumes (sauf l''ail) avec le piment pendant 5 minutes.","Ajouter l''ail 1 minute, déglacer au vin blanc et laisser réduire de moitié.","Ajouter le lait, la crème et l''eau de cuisson des pâtes, laisser réduire 2 à 3 minutes.","Hors du feu, ajouter le parmesan et les pâtes. Trancher le poulet, le poser dessus et parsemer de persil."]'::jsonb, '["2 cuillères à soupe de beurre","3 cuillères à soupe d''huile d''olive","5 blancs de poulet","1 courgette ou courge coupée en dés","1 tête de brocoli","250 g de champignons","1 poivron rouge","1 oignon","3 gousses d''ail","1/2 cuillère à café de piment en flocons","12 cl de vin blanc","12 cl de lait","12 cl de crème liquide","100 g de parmesan râpé","450 g de pâtes papillon","persil"]'::jsonb, 'Italian', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52832', 'Coq au vin', 'https://www.themealdb.com/images/media/meals/qstyvs1505931190.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52832', 'Recette adaptée de TheMealDB', 120, 6, '["Faire dorer les lardons dans l''huile, les retirer. Faire brunir les échalotes 5 à 8 minutes, les mettre de côté avec les lardons.","Sécher les morceaux de poulet et les faire dorer par moitié, puis les réserver.","Ajouter l''ail, verser le cognac et gratter le fond de la cocotte.","Remettre les cuisses et hauts de cuisse avec leur jus, verser un peu de vin en grattant le fond, puis le reste du vin, le bouillon et le concentré de tomate. Ajouter le bouquet garni, poivrer, saler légèrement, remettre lardons et échalotes.","Couvrir et laisser mijoter doucement, ajouter les blancs de poulet et cuire 50 minutes à 1 heure.","Faire dorer les champignons à la poêle. Sortir la viande, retirer le bouquet garni, épaissir la sauce avec la farine mélangée au beurre, puis remettre le tout avec les champignons. Parsemer de persil."]'::jsonb, '["1 cuillère à soupe et demie d''huile d''olive","100 g de lardons","12 petites échalotes","2 cuisses de poulet","4 hauts de cuisse de poulet","2 blancs de poulet","3 gousses d''ail hachées","3 cuillères à soupe de cognac","60 cl de vin rouge","15 cl de bouillon de volaille","2 cuillères à café de concentré de tomate","3 brins de thym","2 brins de romarin","2 feuilles de laurier","250 g de champignons de Paris","2 cuillères à soupe de farine","1 cuillère à café de beurre","persil"]'::jsonb, 'France', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52847', 'Cassoulet de porc', 'https://www.themealdb.com/images/media/meals/wxuvuv1511299147.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52847', 'Recette adaptée de TheMealDB', 180, 4, '["Préchauffer le four à 140 °C. Dans une cocotte allant au four, saisir la viande dans la graisse à feu vif quelques minutes.","Baisser le feu, ajouter l''oignon, l''ail entier, la carotte et le fenouil, et cuire doucement quelques minutes.","Verser le vinaigre en grattant le fond, puis le bouillon, le concentré de tomate et la moitié du romarin et du persil. Laisser mijoter 10 minutes, saler, poivrer.","Couvrir et enfourner 2 heures, en retirant le couvercle la dernière heure. Ajouter les haricots 30 minutes avant la fin.","Parsemer d''herbes et de chapelure, arroser d''un filet d''huile et remettre au four 5 à 10 minutes, jusqu''à ce que le dessus soit doré. Servir avec du pain."]'::jsonb, '["4 cuillères à soupe de graisse d''oie","350 g de porc en dés","1 gros oignon","10 gousses d''ail","1 carotte en rondelles","1 cuillère à café de graines de fenouil","2 cuillères à soupe de vinaigre de vin rouge","60 cl de bouillon de légumes","1 cuillère à soupe de concentré de tomate","2 branches de romarin","1 poignée de persil","400 g de haricots blancs","2 cuillères à soupe de chapelure","un filet d''huile","pain croustillant"]'::jsonb, 'France', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52908', 'Ratatouille', 'https://www.themealdb.com/images/media/meals/wrpwuu1511786491.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52908', 'Recette adaptée de TheMealDB', 70, 4, '["Couper les aubergines, les courgettes et les poivrons en morceaux de 1,5 cm. Ébouillanter les tomates 20 secondes, les peler, les épépiner et les couper en morceaux.","Dans une sauteuse, faire dorer les aubergines dans 2 cuillères à soupe d''huile 5 minutes de chaque côté, les réserver. Faire de même avec les courgettes, puis avec les poivrons, sans trop les cuire.","Faire revenir l''oignon 5 minutes, ajouter l''ail une minute.","Ajouter le vinaigre, le sucre, les tomates et la moitié du basilic.","Remettre les légumes, saler, poivrer et cuire encore 5 minutes. Servir avec le reste du basilic."]'::jsonb, '["2 grosses aubergines","4 courgettes","2 poivrons jaunes","4 grosses tomates","5 cuillères à soupe d''huile d''olive","1 bouquet de basilic","1 oignon","3 gousses d''ail","1 cuillère à café de vinaigre de vin rouge","1 cuillère à café de sucre"]'::jsonb, 'France', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52852', 'Salade niçoise au thon', 'https://www.themealdb.com/images/media/meals/yypwwq1511304979.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52852', 'Recette adaptée de TheMealDB', 45, 4, '["Préchauffer le four à 200 °C. Mélanger les pommes de terre coupées en morceaux avec un peu d''huile, du sel et du poivre, et les faire rôtir 20 minutes en remuant à mi-cuisson.","Faire cuire les œufs 8 à 10 minutes dans l''eau bouillante, les rafraîchir à l''eau froide, les écaler et les couper en deux.","Dans un grand saladier, fouetter l''huile, le vinaigre, les câpres et les tomates coupées. Saler, poivrer.","Ajouter l''oignon, les épinards, le thon et les pommes de terre, mélanger délicatement.","Disposer les œufs dessus et servir aussitôt."]'::jsonb, '["450 g de pommes de terre","2 cuillères à soupe d''huile d''olive","4 œufs","1 cuillère à soupe de vinaigre de vin rouge","2 cuillères à soupe de câpres","50 g d''huile de tournesol","1/2 oignon rouge","100 g de jeunes pousses d''épinards","400 g de thon","tomates"]'::jsonb, 'France', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52802', 'Parmentier de poisson', 'https://www.themealdb.com/images/media/meals/ysxwuq1487323065.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52802', 'Recette adaptée de TheMealDB', 80, 6, '["Cuire les pommes de terre dans de l''eau salée 15 minutes, les égoutter et les écraser avec une cuillère à soupe d''huile, saler, poivrer.","Porter le lait à frémissement avec le poisson, éteindre, couvrir et laisser reposer 3 minutes. Retirer le poisson, le sécher, l''émietter dans un plat à four, en gardant le lait.","Chauffer le reste d''huile, ajouter la farine 30 secondes, verser 200 à 250 ml du lait de cuisson peu à peu, muscade, sel, poivre. Faire épaissir puis ajouter la crème.","Préchauffer le four à 190 °C. Ajouter au plat le poireau, les crevettes et les herbes. Mélanger le zeste et le jus de citron à la sauce, la verser dessus et mélanger doucement.","Étaler la purée dessus, former des pics à la fourchette, parsemer de gruyère et cuire 35 à 40 minutes, jusqu''à ce que ce soit doré et bouillonnant."]'::jsonb, '["900 g de pommes de terre farineuses","2 cuillères à soupe d''huile d''olive","60 cl de lait demi-écrémé","800 g de filets de poisson blanc","1 cuillère à soupe de farine","noix de muscade","3 cuillères à soupe de crème épaisse","1 poireau finement émincé","200 g de crevettes décortiquées crues","1 grosse poignée de persil","1 poignée d''aneth","le zeste et le jus de 1 citron","25 g de gruyère râpé"]'::jsonb, 'British', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52773', 'Saumon teriyaki au miel', 'https://www.themealdb.com/images/media/meals/xxyupu1468262513.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52773', 'Recette adaptée de TheMealDB', 20, 2, '["Mélanger la sauce soja, le saké et le miel pour obtenir la sauce teriyaki.","Mettre le saumon dans la sauce et bien l''enrober.","Chauffer l''huile dans une poêle à feu moyen-doux et faire cuire le saumon des deux côtés jusqu''à ce qu''il soit cuit à cœur et que la sauce épaississe.","Parsemer de sésame et servir aussitôt, par exemple avec du riz."]'::jsonb, '["450 g de saumon","1 cuillère à soupe d''huile d''olive","2 cuillères à soupe de sauce soja","2 cuillères à soupe de saké ou de vin de riz","2 cuillères à soupe de miel","4 cuillères à soupe de graines de sésame"]'::jsonb, 'Japanese', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52820', 'Poulet pané au curry à la japonaise (katsu)', 'https://www.themealdb.com/images/media/meals/vwrpps1503068729.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52820', 'Recette adaptée de TheMealDB', 45, 4, '["Sauce : faire revenir les oignons et l''ail dans l''huile jusqu''à ce qu''ils soient tendres, ajouter les carottes et cuire 10 à 12 minutes à feu doux.","Ajouter la farine et le curry, cuire 1 minute, puis verser peu à peu le bouillon. Ajouter le miel, la sauce soja et le laurier, porter à ébullition et laisser mijoter 20 minutes, jusqu''à épaississement.","Ajouter le garam masala, passer la sauce au tamis et la garder au chaud.","Poulet : saler et poivrer, puis passer chaque blanc dans la farine, l''œuf battu et la chapelure.","Faire dorer dans l''huile chaude 3 à 4 minutes de chaque côté, puis égoutter sur du papier absorbant.","Napper de sauce et servir avec du riz blanc."]'::jsonb, '["4 blancs de poulet aplatis à 1 cm","2 cuillères à soupe de farine","1 œuf battu","100 g de chapelure fine","230 ml d''huile de friture","2 cuillères à soupe d''huile de tournesol","2 oignons émincés","5 gousses d''ail hachées","2 carottes en rondelles","2 cuillères à soupe de farine","4 cuillères à café de curry en poudre","600 ml de bouillon de volaille","2 cuillères à café de miel","4 cuillères à café de sauce soja","1 feuille de laurier","1 cuillère à café de garam masala","riz blanc pour servir"]'::jsonb, 'Japanese', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52945', 'Poulet Kung Pao', 'https://www.themealdb.com/images/media/meals/1525872624.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52945', 'Recette adaptée de TheMealDB', 40, 4, '["Mélanger le saké, la sauce soja, l''huile de sésame et la fécule diluée dans l''eau, puis diviser ce mélange en deux.","Enrober le poulet de la moitié du mélange et laisser mariner au frais 30 minutes.","Dans une poêle, mélanger le reste du mélange avec le piment, le vinaigre et le sucre, puis ajouter les oignons nouveaux, l''ail, les châtaignes d''eau et les cacahuètes. Chauffer doucement jusqu''à ce que la sauce embaume.","Pendant ce temps, faire sauter le poulet égoutté dans une grande poêle jusqu''à ce que le jus soit clair.","Ajouter le poulet à la sauce et laisser mijoter jusqu''à ce qu''elle épaississe."]'::jsonb, '["2 cuillères à soupe de saké ou de vin de riz","2 cuillères à soupe de sauce soja","2 cuillères à soupe d''huile de sésame","2 cuillères à soupe de fécule de maïs","2 cuillères à soupe d''eau","500 g de poulet en morceaux","1 cuillère à soupe de piment en poudre","1 cuillère à café de vinaigre de riz","1 cuillère à soupe de sucre roux","4 oignons nouveaux émincés","6 gousses d''ail","220 g de châtaignes d''eau","100 g de cacahuètes"]'::jsonb, 'Chinese', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '53191', 'Pad thaï aux crevettes', 'https://www.themealdb.com/images/media/meals/rg9ze01763479093.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/53191', 'Recette adaptée de TheMealDB', 25, 2, '["Mettre les nouilles dans un grand bol, couvrir d''eau bouillante, laisser 4 minutes, égoutter et rincer à l''eau froide.","Mélanger le jus de citron vert, le piment, le sucre et le nuoc-mâm. Préparer tous les autres ingrédients près du feu.","Chauffer l''huile et faire sauter les crevettes jusqu''à ce qu''elles soient chaudes. Ajouter les oignons nouveaux et les nouilles, mélanger.","Verser le mélange au citron vert, ajouter les germes de soja et la moitié des cacahuètes et de la coriandre. Cuire 1 minute.","Dresser dans un grand plat avec le reste des cacahuètes et de la coriandre, et servir avec des quartiers de citron vert et de la sauce chili douce."]'::jsonb, '["125 g de nouilles de riz","le jus de 3 citrons verts","1/2 cuillère à café de piment de Cayenne","2 cuillères à café de sucre muscovado","2 cuillères à soupe de sauce nuoc-mâm","2 cuillères à soupe d''huile végétale","200 g de crevettes tigrées","4 oignons nouveaux finement émincés","140 g de germes de soja","25 g de cacahuètes","1 poignée de coriandre","2 citrons verts pour servir","sauce chili douce"]'::jsonb, 'Thai', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52826', 'Chili de bœuf mijoté', 'https://www.themealdb.com/images/media/meals/uuqvwu1504629254.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52826', 'Recette adaptée de TheMealDB', 210, 6, '["Préchauffer le four à 120 °C. Mixer brièvement les oignons et l''ail. Saisir la viande de tous les côtés dans une cocotte avec de l''huile, puis la réserver.","Faire dorer le chorizo dans la même cocotte, le retirer. Y cuire l''oignon, l''ail, les épices, les herbes et les piments jusqu''à ce qu''ils soient tendres.","Saler, poivrer, ajouter le vinaigre, les tomates, le ketchup et le sucre.","Remettre toute la viande avec 400 ml d''eau (ou de vin rouge), porter à frémissement, couvrir et enfourner.","Après 2 heures, ajouter les haricots et cuire encore 1 heure. Avant de servir, effilocher la viande avec deux fourchettes."]'::jsonb, '["1 kg de bœuf","3 oignons","4 gousses d''ail","un filet d''huile d''olive","300 g de chorizo","2 cuillères à café de cumin","2 cuillères à café de piment de la Jamaïque","1 cuillère à café de clous de girofle","1 grand bâton de cannelle","3 feuilles de laurier","2 cuillères à café d''origan séché","2 piments ancho","3 cuillères à soupe de vinaigre balsamique","2 boîtes de 400 g de tomates","2 cuillères à soupe de ketchup","2 cuillères à soupe de sucre roux","2 boîtes de 400 g de haricots borlotti"]'::jsonb, 'Mexican', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52870', 'Fajitas aux pois chiches', 'https://www.themealdb.com/images/media/meals/tvtxpq1511464705.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52870', 'Recette adaptée de TheMealDB', 40, 4, '["Préchauffer le four à 200 °C. Égoutter et sécher les pois chiches, les mélanger avec l''huile et le paprika sur une plaque, et les rôtir 20 à 25 minutes jusqu''à ce qu''ils soient dorés et croustillants.","Pendant ce temps, laisser mariner les tomates et l''oignon dans le vinaigre.","Écraser l''avocat à la fourchette avec le jus de citron vert, saler, poivrer. Mélanger la crème aigre avec la harissa.","Chauffer une poêle-gril presque à fumer, y griller les tortillas une à une des deux côtés.","Garnir chaque tortilla de crème à la harissa, de pois chiches, de guacamole, de tomates marinées et de coriandre, avec des quartiers de citron vert."]'::jsonb, '["400 g de pois chiches","1 cuillère à soupe d''huile d''olive","1 pincée de paprika","2 petites tomates coupées en morceaux","1 oignon rouge finement émincé","2 cuillères à café de vinaigre de vin rouge","1 avocat","le jus de 1 citron vert","1 citron vert coupé en quartiers","100 g de crème aigre","2 cuillères à café de harissa","4 tortillas de maïs","coriandre"]'::jsonb, 'Mexican', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52872', 'Tortilla espagnole aux pommes de terre', 'https://www.themealdb.com/images/media/meals/quuxsx1511476154.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52872', 'Recette adaptée de TheMealDB', 50, 4, '["Faire cuire l''oignon doucement dans l''huile et le beurre, sans coloration, environ 15 minutes.","Ajouter les pommes de terre en tranches, couvrir et cuire encore 15 à 20 minutes en remuant de temps en temps.","Quand elles sont tendres, ajouter 2 gousses d''ail écrasées puis les œufs battus. Couvrir et laisser cuire doucement.","Au bout de 20 minutes, les bords et le dessous sont dorés, le dessus pris. Retourner la tortilla sur une assiette et la remettre dans la poêle pour finir la cuisson.","Servir tiède ou froide avec du persil. Accompagner de tranches de baguette frottées à l''ail et garnies de tomate râpée, de sel et d''un filet d''huile d''olive."]'::jsonb, '["1 oignon émincé","4 cuillères à soupe d''huile d''olive","25 g de beurre","400 g de pommes de terre","6 gousses d''ail","8 œufs","1 poignée de persil","1 baguette","4 tomates grappe"]'::jsonb, 'Spanish', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '53014', 'Pizza margherita maison', 'https://www.themealdb.com/images/media/meals/x0lk931587671540.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/53014', 'Recette adaptée de TheMealDB', 60, 2, '["Préchauffer le four à 230 °C. Faire dissoudre le sucre et émietter la levure dans l''eau tiède, laisser reposer 10 à 15 minutes jusqu''à ce que le mélange mousse.","Tamiser la farine et le sel dans un saladier, creuser un puits, verser le mélange à la levure et l''huile, mélanger jusqu''à ce que la pâte se tienne.","Pétrir 10 minutes sur un plan fariné, jusqu''à ce que la pâte soit lisse et souple, puis l''étaler sur une plaque huilée.","Étaler le coulis de tomate jusqu''au bord, répartir la mozzarella, ajouter l''origan et le poivre, et un filet d''huile.","Cuire 10 à 12 minutes, jusqu''à ce que le fromage prenne un peu de couleur. Poser le basilic et servir."]'::jsonb, '["150 ml d''eau","1 cuillère à café de sucre","15 g de levure fraîche","225 g de farine","1 cuillère et demie à café de sel","un filet d''huile d''olive","80 g de coulis de tomate","70 g de mozzarella","origan","feuilles de basilic","poivre noir"]'::jsonb, 'Italian', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '53287', 'Tajine de poulet aux carottes et patates douces', 'https://www.themealdb.com/images/media/meals/d8bfyg1764117503.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/53287', 'Recette adaptée de TheMealDB', 100, 4, '["Mettre les oignons, le céleri, la coriandre et le persil dans une grande cocotte, ajouter les épices, du sel et du poivre. Poser les hauts de cuisse dessus et arroser d''huile.","Couvrir et laisser mijoter à feu doux environ 40 minutes, jusqu''à ce que le poulet soit tendre. Faire tremper les raisins secs dans de l''eau chaude 10 minutes, puis les égoutter.","Préchauffer le four à 200 °C. Transférer le mélange dans un plat à tajine ou une cocotte allant au four, ajouter la patate douce et les carottes, couvrir.","Cuire au four environ 40 minutes, jusqu''à ce que la patate douce soit tendre. Ajouter les raisins secs et les pruneaux, et cuire encore 10 minutes à couvert."]'::jsonb, '["2 oignons émincés","2 branches de céleri en tranches","1/2 bouquet de coriandre","1/2 bouquet de persil","1/2 cuillère à café de curcuma","1/2 cuillère à café de cumin moulu","1/2 cuillère à café de paprika","1/4 de cuillère à café de gingembre moulu","1/4 de cuillère à café de piment de Cayenne","sel","poivre noir","4 hauts de cuisse de poulet","un filet d''huile d''olive","40 g de raisins secs","25 cl de bouillon de volaille","1 grosse patate douce","3 carottes finement tranchées","40 g de pruneaux"]'::jsonb, 'Algerian', 'fr', false) on conflict (source, source_id) do nothing;
insert into public.catalogue_commun (source, source_id, titre, photo_url, photo_auteur, photo_licence, texte_licence, attribution_url, attribution_texte, minutes, portions, etapes, ingredients, cuisine, langue, publiable) values ('themealdb', '52963', 'Shakshuka', 'https://www.themealdb.com/images/media/meals/g373701551450225.jpg', null, 'API-AUTORISEE', 'API-AUTORISEE', 'https://www.themealdb.com/meal/52963', 'Recette adaptée de TheMealDB', 35, 2, '["Chauffer l''huile dans une poêle avec couvercle, y faire fondre les oignons, le piment, l''ail et les tiges de coriandre pendant 5 minutes.","Ajouter les tomates et le sucre, laisser bouillonner 8 à 10 minutes, jusqu''à ce que la sauce épaississe.","Creuser 4 petits trous dans la sauce avec le dos d''une cuillère et casser un œuf dans chacun.","Couvrir et cuire à feu doux 6 à 8 minutes, jusqu''à la cuisson désirée des œufs.","Parsemer de feuilles de coriandre et de feta, et servir avec du pain croustillant."]'::jsonb, '["1 cuillère à soupe d''huile d''olive","2 oignons rouges hachés","1 piment rouge finement haché","1 gousse d''ail","de la coriandre fraîche","800 g de tomates cerises","1 cuillère à soupe de sucre en poudre","4 œufs","un peu de feta émiettée"]'::jsonb, 'Egyptian', 'fr', false) on conflict (source, source_id) do nothing;
